--- services/queue-bff/tests/pact/consumer/account_consumer_test.go (681 lines) ---
// Package consumer holds queue-bff's Pact V2 consumer-contract tests.
//
// This is the FIRST Pact contract in the Queue vertical (epic #1232 Task 5):
// queue-bff (consumer) → queue-svc (provider). The account handlers, routes,
// and gRPC client were already shipped by the Queue foundation sub-PR
// (mirrors services/ask-svc's boot skeleton) with every AccountService RPC
// aborting UNIMPLEMENTED; Tasks 1–4 landed real implementations for
// CreateAccountGroup, ListAccountGroups, ConnectAccount, and ListAccounts in
// queue-svc, so this contract locks the wire shape those four queue-bff
// routes depend on. The remaining AccountService RPCs (GetAccount,
// UpdateAccount, DisconnectAccount, SyncAccounts, RefreshAccount,
// UpdateAccountGroup, DeleteAccountGroup) still abort UNIMPLEMENTED in
// queue-svc, so no Pact interaction exists for them yet — they join this
// file as their handlers land (Task 6+ of this epic, or a follow-on story).
//
// The contract JSON at ../../../pacts/queue-bff-queue-svc-account.json is
// the authored source of truth (published to the broker by `make
// pact-publish SVC=queue-bff` and verified by queue-svc's
// provider-verification test — the Task 6 deliverable). These tests guard
// that the committed contract is present and well-formed and that it
// records the expected interaction + response shape. Mirrors
// services/ask-bff/tests/pact/consumer/survey_consumer_test.go exactly,
// substituting Survey→Account, adapted to queue-bff's dependency-light test
// style (stdlib testing, no testify — queue-bff does not vendor testify).
//
// Every interaction here models the queue-bff→queue-svc gRPC hop
// (request.path is the raw gRPC method path, e.g.
// "/omnicore.queue.account.v1.AccountService/CreateAccountGroup";
// response.body is the unwrapped proto response, e.g.
// {"group": {...}} for CreateAccountGroupResponse) — NOT the
// browser→queue-bff REST envelope ({"data": ...}). The REST envelope is
// asserted separately by internal/handlers/account_test.go's happy-path
// tests. This mirrors exactly how the ask-bff List interaction models
// ListResponse ({"surveys": [...], "next_page_token": ...}), never the REST
// DTO.
//
// Provider states (Task 6's queue-svc verifier must seed these EXACT
// strings — they are the consumer/provider interface contract):
//   - "an org exists" (CreateAccountGroup): org_id is sourced from the
//     caller's claims, never the request body (queue_svc.handlers.account.
//     AccountHandler.CreateAccountGroup), and the RPC's own call is what
//     inserts the group row — no pre-existing row needs seeding.
//   - "org has one account group" (ListAccountGroups AND ConnectAccount):
//     ListAccountGroups needs a row to return; ConnectAccount's group_id is
//     validated as a well-formed UUID and then looked up via
//     QueueAccountRepo.account_group_type() — GroupNotFound (NOT_FOUND) if
//     it doesn't already exist — so ConnectAccount's happy path ALSO
//     requires a pre-existing account group, not merely "an org exists".
//     Both interactions reuse this state description; queue-svc's state
//     handler seeds one deterministic AccountGroup row (id
//     22222222-2222-2222-2222-222222222222) both interactions reference.
//   - "org has one connected account" (ListAccounts): needs a SocialAccount
//     row (which itself requires its parent AccountGroup) to return.
package consumer

import (
	"encoding/json"
	"os"
	"testing"
)

const accountPactFile = "../../../pacts/queue-bff-queue-svc-account.json"

// pactContract is the minimal structure needed to inspect a Pact V2 contract.
type pactContract struct {
	Interactions []struct {
		Description   string `json:"description"`
		ProviderState string `json:"providerState"`
	} `json:"interactions"`
}

// loadContract reads and unmarshals the pact contract JSON at path.
func loadContract(t *testing.T, path string) pactContract {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("pact contract must exist at %s: %v", path, err)
	}
	var c pactContract
	if err := json.Unmarshal(data, &c); err != nil {
		t.Fatalf("pact contract must be valid JSON: %v", err)
	}
	return c
}

// hasInteraction reports whether the contract records an interaction with
// the given description.
func hasInteraction(c pactContract, description string) bool {
	for _, i := range c.Interactions {
		if i.Description == description {
			return true
		}
	}
	return false
}

func loadAccountContract(t *testing.T) pactContract {
	t.Helper()
	return loadContract(t, accountPactFile)
}

// TestPactContractAccountFileExists guards that the account contract JSON is
// present at the expected path.
func TestPactContractAccountFileExists(t *testing.T) {
	if _, err := os.Stat(accountPactFile); err != nil {
		t.Fatalf("pact contract should be at services/queue-bff/pacts/queue-bff-queue-svc-account.json: %v", err)
	}
}

// TestPact_AccountSvc_ContractHasSixInteractions asserts the contract
// contains exactly the CreateAccountGroup, ListAccountGroups, ConnectAccount,
// and ListAccounts interactions landed by Tasks 1–4, plus the
// UpdateAccountGroup and DeleteAccountGroup interactions landed by #1238.
// The remaining AccountService RPCs (GetAccount, UpdateAccount,
// DisconnectAccount, SyncAccounts, RefreshAccount) still abort UNIMPLEMENTED
// in queue-svc, so no contract exists for them yet — they join this file as
// their handlers land in #1236.
func TestPact_AccountSvc_ContractHasSixInteractions(t *testing.T) {
	c := loadAccountContract(t)
	if len(c.Interactions) != 6 {
		t.Errorf("account contract has %d interactions; want 6", len(c.Interactions))
	}
}

// ---------- AccountService.CreateAccountGroup ----------

// createAccountGroupInteraction is the full-fidelity shape of the
// CreateAccountGroup interaction's request + response — pactContract is
// shape-minimal, mirroring ask-bff's surveyCreateInteraction.
type createAccountGroupInteraction struct {
	Description string `json:"description"`
	Request     struct {
		Body map[string]any `json:"body"`
	} `json:"request"`
	Response struct {
		Body struct {
			Group map[string]any `json:"group"`
		} `json:"body"`
	} `json:"response"`
}

// loadCreateAccountGroupInteraction reads the full CreateAccountGroup
// interaction (request body + response group) from the contract file.
func loadCreateAccountGroupInteraction(t *testing.T) createAccountGroupInteraction {
	t.Helper()
	data, err := os.ReadFile(accountPactFile)
	if err != nil {
		t.Fatalf("read contract: %v", err)
	}
	var full struct {
		Interactions []createAccountGroupInteraction `json:"interactions"`
	}
	if err := json.Unmarshal(data, &full); err != nil {
		t.Fatalf("unmarshal contract: %v", err)
	}
	for _, i := range full.Interactions {
		if i.Description == "AccountService.CreateAccountGroup — happy path" {
			return i
		}
	}
	t.Fatal("AccountService.CreateAccountGroup — happy path interaction not found")
	return createAccountGroupInteraction{}
}

// TestPact_AccountSvc_CreateAccountGroup_Happy asserts the contract records
// the CreateAccountGroup happy-path interaction.
func TestPact_AccountSvc_CreateAccountGroup_Happy(t *testing.T) {
	c := loadAccountContract(t)
	if !hasInteraction(c, "AccountService.CreateAccountGroup — happy path") {
		t.Error("contract must contain AccountService.CreateAccountGroup happy path interaction")
	}
}

// TestPact_AccountSvc_CreateAccountGroup_HasProviderState asserts the
// CreateAccountGroup interaction carries the provider state queue-svc's
// verifier seeds against. Unlike ListAccountGroups (which seeds a row),
// CreateAccountGroup's own RPC call is what inserts the row — org_id comes
// from the caller's claims, never a pre-existing row — so "an org exists"
// needs no seeding at all.
func TestPact_AccountSvc_CreateAccountGroup_HasProviderState(t *testing.T) {
	c := loadAccountContract(t)
	const want = "an org exists"
	for _, i := range c.Interactions {
		if i.Description == "AccountService.CreateAccountGroup — happy path" {
			if i.ProviderState != want {
				t.Errorf("CreateAccountGroup provider state = %q; want %q", i.ProviderState, want)
			}
			return
		}
	}
	t.Fatal("AccountService.CreateAccountGroup — happy path interaction not found")
}

// TestPact_AccountSvc_CreateAccountGroup_RequestBodyHasNameAndGroupType pins
// the CreateAccountGroupRequest fields the queue-bff handler populates from
// the REST POST body (handlers/account.go's createAccountGroupRequest →
// accountv1.CreateAccountGroupRequest): name must be non-empty and
// group_type must be a numeric enum ordinal (GROUP_TYPE_ION = 2 — GROUP_
// TYPE_LIVE is rejected FAILED_PRECONDITION and GROUP_TYPE_UNSPECIFIED is
// rejected INVALID_ARGUMENT by queue-svc, so the happy-path fixture must use
// a creatable type) so the provider's dispatch has a realistic request to
// create an account group from.
func TestPact_AccountSvc_CreateAccountGroup_RequestBodyHasNameAndGroupType(t *testing.T) {
	i := loadCreateAccountGroupInteraction(t)
	name, ok := i.Request.Body["name"].(string)
	if !ok || name == "" {
		t.Errorf("CreateAccountGroup request body name = %v; want a non-empty string", i.Request.Body["name"])
	}
	groupType, ok := i.Request.Body["group_type"].(float64)
	if !ok || groupType != 2 {
		t.Errorf("CreateAccountGroup request body group_type = %v; want 2 (GROUP_TYPE_ION)", i.Request.Body["group_type"])
	}
}

// TestPact_AccountSvc_CreateAccountGroup_ResponseGroupHasMatchedFields pins
// the field set the consumer requires on the created AccountGroup — the
// same fields the provider contract's matchingRules assert by type.
func TestPact_AccountSvc_CreateAccountGroup_ResponseGroupHasMatchedFields(t *testing.T) {
	i := loadCreateAccountGroupInteraction(t)
	if len(i.Response.Body.Group) == 0 {
		t.Fatal("CreateAccountGroup interaction response.group must be present")
	}
	for _, field := range []string{"id", "org_id", "name", "group_type", "created_at"} {
		if _, ok := i.Response.Body.Group[field]; !ok {
			t.Errorf("CreateAccountGroup response group must include %q", field)
		}
	}
}

// TestPact_AccountSvc_CreateAccountGroup_ResponseGroupReflectsRequest pins
// the documented CreateAccountGroup contract: the returned group echoes the
// requested name and group_type, plus a non-empty id.
func TestPact_AccountSvc_CreateAccountGroup_ResponseGroupReflectsRequest(t *testing.T) {
	i := loadCreateAccountGroupInteraction(t)
	g := i.Response.Body.Group

	if id, ok := g["id"].(string); !ok || id == "" {
		t.Errorf("CreateAccountGroup response group id = %v; want a non-empty string", g["id"])
	}
	if g["name"] != i.Request.Body["name"] {
		t.Errorf("CreateAccountGroup response group name = %v; want it to echo the request name %v", g["name"], i.Request.Body["name"])
	}
	if g["group_type"] != i.Request.Body["group_type"] {
		t.Errorf("CreateAccountGroup response group group_type = %v; want it to echo the request group_type %v", g["group_type"], i.Request.Body["group_type"])
	}
}

// ---------- AccountService.ListAccountGroups ----------

// listAccountGroupsResponseBody is the full-fidelity shape of the
// ListAccountGroups interaction's response body.
type listAccountGroupsResponseBody struct {
	Groups        []map[string]any `json:"groups"`
	NextPageToken string           `json:"next_page_token"`
}

// loadListAccountGroupsResponse returns the named interaction's full
// response body.
func loadListAccountGroupsResponse(t *testing.T, description string) listAccountGroupsResponseBody {
	t.Helper()
	data, err := os.ReadFile(accountPactFile)
	if err != nil {
		t.Fatalf("read contract: %v", err)
	}
	var full struct {
		Interactions []struct {
			Description string `json:"description"`
			Response    struct {
				Body listAccountGroupsResponseBody `json:"body"`
			} `json:"response"`
		} `json:"interactions"`
	}
	if err := json.Unmarshal(data, &full); err != nil {
		t.Fatalf("unmarshal contract: %v", err)
	}
	for _, i := range full.Interactions {
		if i.Description == description {
			return i.Response.Body
		}
	}
	t.Fatalf("interaction %q not found", description)
	return listAccountGroupsResponseBody{}
}

// TestPact_AccountSvc_ListAccountGroups_Happy asserts the contract records
// the ListAccountGroups happy-path interaction.
func TestPact_AccountSvc_ListAccountGroups_Happy(t *testing.T) {
	c := loadAccountContract(t)
	if !hasInteraction(c, "AccountService.ListAccountGroups — happy path") {
		t.Error("contract must contain AccountService.ListAccountGroups happy path interaction")
	}
}

// TestPact_AccountSvc_ListAccountGroups_HasProviderState asserts the
// ListAccountGroups interaction carries the provider state queue-svc's
// verifier seeds against.
func TestPact_AccountSvc_ListAccountGroups_HasProviderState(t *testing.T) {
	c := loadAccountContract(t)
	const want = "org has one account group"
	for _, i := range c.Interactions {
		if i.Description == "AccountService.ListAccountGroups — happy path" {
			if i.ProviderState != want {
				t.Errorf("ListAccountGroups provider state = %q; want %q", i.ProviderState, want)
			}
			return
		}
	}
	t.Fatal("AccountService.ListAccountGroups — happy path interaction not found")
}

// TestPact_AccountSvc_ListAccountGroups_ResponseGroupHasMatchedFields pins
// the field set the consumer requires on each returned AccountGroup — the
// same fields the provider contract's matchingRules assert by type. A field
// dropped from queue-svc's AccountGroup wire shape breaks this (and the
// provider verification).
func TestPact_AccountSvc_ListAccountGroups_ResponseGroupHasMatchedFields(t *testing.T) {
	body := loadListAccountGroupsResponse(t, "AccountService.ListAccountGroups — happy path")
	if len(body.Groups) == 0 {
		t.Fatal("ListAccountGroups response.groups must have at least one group")
	}
	g := body.Groups[0]
	for _, field := range []string{"id", "org_id", "name", "group_type", "created_at"} {
		if _, ok := g[field]; !ok {
			t.Errorf("ListAccountGroups response group must include %q", field)
		}
	}
}

// ---------- AccountService.ConnectAccount ----------

// connectAccountInteraction is the full-fidelity shape of the
// ConnectAccount interaction's request + response.
type connectAccountInteraction struct {
	Description string `json:"description"`
	Request     struct {
		Body map[string]any `json:"body"`
	} `json:"request"`
	Response struct {
		Body struct {
			Account map[string]any `json:"account"`
		} `json:"body"`
	} `json:"response"`
}

// loadConnectAccountInteraction reads the full ConnectAccount interaction
// from the contract file.
func loadConnectAccountInteraction(t *testing.T) connectAccountInteraction {
	t.Helper()
	data, err := os.ReadFile(accountPactFile)
	if err != nil {
		t.Fatalf("read contract: %v", err)
	}
	var full struct {
		Interactions []connectAccountInteraction `json:"interactions"`
	}
	if err := json.Unmarshal(data, &full); err != nil {
		t.Fatalf("unmarshal contract: %v", err)
	}
	for _, i := range full.Interactions {
		if i.Description == "AccountService.ConnectAccount — happy path" {
			return i
		}
	}
	t.Fatal("AccountService.ConnectAccount — happy path interaction not found")
	return connectAccountInteraction{}
}

// TestPact_AccountSvc_ConnectAccount_Happy asserts the contract records the
// ConnectAccount happy-path interaction.
func TestPact_AccountSvc_ConnectAccount_Happy(t *testing.T) {
	c := loadAccountContract(t)
	if !hasInteraction(c, "AccountService.ConnectAccount — happy path") {
		t.Error("contract must contain AccountService.ConnectAccount happy path interaction")
	}
}

// TestPact_AccountSvc_ConnectAccount_HasProviderState asserts the
// ConnectAccount interaction carries the provider state queue-svc's
// verifier seeds against. Unlike CreateAccountGroup, ConnectAccount's
// group_id is validated as a well-formed UUID and then looked up via
// QueueAccountRepo.account_group_type() — GroupNotFound (NOT_FOUND) if it
// doesn't already exist (see queue_svc.handlers.account) — so its happy
// path requires a PRE-EXISTING account group, reusing ListAccountGroups'
// "org has one account group" state rather than the bare "an org exists"
// state Create-style RPCs use.
func TestPact_AccountSvc_ConnectAccount_HasProviderState(t *testing.T) {
	c := loadAccountContract(t)
	const want = "org has one account group"
	for _, i := range c.Interactions {
		if i.Description == "AccountService.ConnectAccount — happy path" {
			if i.ProviderState != want {
				t.Errorf("ConnectAccount provider state = %q; want %q", i.ProviderState, want)
			}
			return
		}
	}
	t.Fatal("AccountService.ConnectAccount — happy path interaction not found")
}

// TestPact_AccountSvc_ConnectAccount_RequestBodyHasGroupIDPlatformHandle
// pins the ConnectAccountRequest fields the queue-bff handler populates
// from the REST POST body (handlers/account.go's connectAccountRequest →
// accountv1.ConnectAccountRequest): group_id must reference the account
// group queue-svc's "org has one account group" state seeds (an exact,
// non-matched literal — the whole point of the state is that this id
// exists), platform and handle must both be non-empty.
func TestPact_AccountSvc_ConnectAccount_RequestBodyHasGroupIDPlatformHandle(t *testing.T) {
	i := loadConnectAccountInteraction(t)
	groupID, ok := i.Request.Body["group_id"].(string)
	if !ok || groupID == "" {
		t.Errorf("ConnectAccount request body group_id = %v; want a non-empty string", i.Request.Body["group_id"])
	}
	platform, ok := i.Request.Body["platform"].(string)
	if !ok || platform == "" {
		t.Errorf("ConnectAccount request body platform = %v; want a non-empty string", i.Request.Body["platform"])
	}
	handle, ok := i.Request.Body["handle"].(string)
	if !ok || handle == "" {
		t.Errorf("ConnectAccount request body handle = %v; want a non-empty string", i.Request.Body["handle"])
	}
}

// TestPact_AccountSvc_ConnectAccount_ResponseAccountHasMatchedFields pins
// the field set the consumer requires on the connected SocialAccount — the
// same fields the provider contract's matchingRules assert by type.
func TestPact_AccountSvc_ConnectAccount_ResponseAccountHasMatchedFields(t *testing.T) {
	i := loadConnectAccountInteraction(t)
	if len(i.Response.Body.Account) == 0 {
		t.Fatal("ConnectAccount interaction response.account must be present")
	}
	for _, field := range []string{
		"id", "org_id", "group_id", "platform", "handle", "status", "last_synced_at",
	} {
		if _, ok := i.Response.Body.Account[field]; !ok {
			t.Errorf("ConnectAccount response account must include %q", field)
		}
	}
}

// TestPact_AccountSvc_ConnectAccount_ResponseAccountReflectsConnectedDefaults
// pins the documented ConnectAccount contract (OAuth is out of scope for
// this build — see the AccountService proto doc comment): a freshly
// connected account carries status="connected" and an empty
// last_synced_at, plus a non-empty id and group_id echoing the request.
func TestPact_AccountSvc_ConnectAccount_ResponseAccountReflectsConnectedDefaults(t *testing.T) {
	i := loadConnectAccountInteraction(t)
	a := i.Response.Body.Account

	if id, ok := a["id"].(string); !ok || id == "" {
		t.Errorf("ConnectAccount response account id = %v; want a non-empty string", a["id"])
	}
	if status, ok := a["status"].(string); !ok || status != "connected" {
		t.Errorf("ConnectAccount response account status = %v; want \"connected\"", a["status"])
	}
	if a["group_id"] != i.Request.Body["group_id"] {
		t.Errorf("ConnectAccount response account group_id = %v; want it to echo the request group_id %v", a["group_id"], i.Request.Body["group_id"])
	}
	if lastSynced, ok := a["last_synced_at"].(string); !ok || lastSynced != "" {
		t.Errorf("ConnectAccount response account last_synced_at = %v; want empty (never synced)", a["last_synced_at"])
	}
}

// ---------- AccountService.ListAccounts ----------

// listAccountsResponseBody is the full-fidelity shape of the ListAccounts
// interaction's response body.
type listAccountsResponseBody struct {
	Accounts      []map[string]any `json:"accounts"`
	NextPageToken string           `json:"next_page_token"`
}

// loadListAccountsResponse returns the named interaction's full response
// body.
func loadListAccountsResponse(t *testing.T, description string) listAccountsResponseBody {
	t.Helper()
	data, err := os.ReadFile(accountPactFile)
	if err != nil {
		t.Fatalf("read contract: %v", err)
	}
	var full struct {
		Interactions []struct {
			Description string `json:"description"`
			Response    struct {
				Body listAccountsResponseBody `json:"body"`
			} `json:"response"`
		} `json:"interactions"`
	}
	if err := json.Unmarshal(data, &full); err != nil {
		t.Fatalf("unmarshal contract: %v", err)
	}
	for _, i := range full.Interactions {
		if i.Description == description {
			return i.Response.Body
		}
	}
	t.Fatalf("interaction %q not found", description)
	return listAccountsResponseBody{}
}

// TestPact_AccountSvc_ListAccounts_Happy asserts the contract records the
// ListAccounts happy-path interaction.
func TestPact_AccountSvc_ListAccounts_Happy(t *testing.T) {
	c := loadAccountContract(t)
	if !hasInteraction(c, "AccountService.ListAccounts — happy path") {
		t.Error("contract must contain AccountService.ListAccounts happy path interaction")
	}
}

// TestPact_AccountSvc_ListAccounts_HasProviderState asserts the
// ListAccounts interaction carries the provider state queue-svc's verifier
// seeds against — a connected SocialAccount row (which itself requires its
// parent AccountGroup) to return.
func TestPact_AccountSvc_ListAccounts_HasProviderState(t *testing.T) {
	c := loadAccountContract(t)
	const want = "org has one connected account"
	for _, i := range c.Interactions {
		if i.Description == "AccountService.ListAccounts — happy path" {
			if i.ProviderState != want {
				t.Errorf("ListAccounts provider state = %q; want %q", i.ProviderState, want)
			}
			return
		}
	}
	t.Fatal("AccountService.ListAccounts — happy path interaction not found")
}

// TestPact_AccountSvc_ListAccounts_ResponseAccountHasMatchedFields pins the
// field set the consumer requires on each returned SocialAccount — the
// same fields the provider contract's matchingRules assert by type, and the
// same field set ConnectAccount requires (ListAccountsResponse and
// ConnectAccountResponse both wrap the same SocialAccount message). A field
// dropped from queue-svc's SocialAccount wire shape breaks this (and the
// provider verification).
func TestPact_AccountSvc_ListAccounts_ResponseAccountHasMatchedFields(t *testing.T) {
	body := loadListAccountsResponse(t, "AccountService.ListAccounts — happy path")
	if len(body.Accounts) == 0 {
		t.Fatal("ListAccounts response.accounts must have at least one account")
	}
	a := body.Accounts[0]
	for _, field := range []string{
		"id", "org_id", "group_id", "platform", "handle", "status", "last_synced_at",
	} {
		if _, ok := a[field]; !ok {
			t.Errorf("ListAccounts response account must include %q", field)
		}
	}
}

// TestPact_AccountSvc_ListAccounts_RequestBodyHasGroupIDFilter pins the
// ListAccountsRequest's optional group_id filter the queue-bff handler
// populates from the ?group_id= query param (handlers/account.go's
// AccountHandler.List): this fixture models the filtered case (list within
// one group), the more common path from the account-detail UI.
func TestPact_AccountSvc_ListAccounts_RequestBodyHasGroupIDFilter(t *testing.T) {
	data, err := os.ReadFile(accountPactFile)
	if err != nil {
		t.Fatalf("read contract: %v", err)
	}
	var full struct {
		Interactions []struct {
			Description string `json:"description"`
			Request     struct {
				Body map[string]any `json:"body"`
			} `json:"request"`
		} `json:"interactions"`
	}
	if err := json.Unmarshal(data, &full); err != nil {
		t.Fatalf("unmarshal contract: %v", err)
	}
	for _, i := range full.Interactions {
		if i.Description == "AccountService.ListAccounts — happy path" {
			groupID, ok := i.Request.Body["group_id"].(string)
			if !ok || groupID == "" {
				t.Errorf("ListAccounts request body group_id = %v; want a non-empty string", i.Request.Body["group_id"])
			}
			return
		}
	}
	t.Fatal("AccountService.ListAccounts — happy path interaction not found")
}

// ---------- AccountService.UpdateAccountGroup / DeleteAccountGroup (#1238) ----------

// TestPact_AccountSvc_UpdateAccountGroup_Happy asserts the contract records
// the rename interaction.
func TestPact_AccountSvc_UpdateAccountGroup_Happy(t *testing.T) {
	c := loadAccountContract(t)
	if !hasInteraction(c, "AccountService.UpdateAccountGroup — happy path") {
		t.Error("contract must record the UpdateAccountGroup happy-path interaction")
	}
}

// TestPact_AccountSvc_UpdateAccountGroup_HasOwnProviderState pins the state
// string queue-svc's verifier seeds. It is deliberately NOT the shared "org
// has one account group" state: UpdateAccountGroup is a real write that
// renames its fixture, so it gets its own org and group id to keep it from
// changing the name ListAccountGroups asserts.
func TestPact_AccountSvc_UpdateAccountGroup_HasOwnProviderState(t *testing.T) {
