// postInteraction is the full-fidelity shape of a Post RPC's request +
// response — pactContract is shape-minimal, mirroring
// createAccountGroupInteraction.
type postInteraction struct {
	Description string `json:"description"`
	Request     struct {
		Body map[string]any `json:"body"`
	} `json:"request"`
	Response struct {
		Body struct {
			Post map[string]any `json:"post"`
		} `json:"body"`
	} `json:"response"`
}

// loadPostInteraction reads the named interaction's full request body +
// response.post from the contract file.
func loadPostInteraction(t *testing.T, description string) postInteraction {
	t.Helper()
	data, err := os.ReadFile(postPactFile)
	if err != nil {
		t.Fatalf("read contract: %v", err)
	}
	var full struct {
		Interactions []postInteraction `json:"interactions"`
	}
	if err := json.Unmarshal(data, &full); err != nil {
		t.Fatalf("unmarshal contract: %v", err)
	}
	for _, i := range full.Interactions {
		if i.Description == description {
			return i
		}
	}
	t.Fatalf("interaction %q not found", description)
	return postInteraction{}
}

