// Package consumer holds queue-bff's Pact V2 consumer-contract tests.
//
// This file adds the queue-bff (consumer) → range-svc (provider) contract
// (Post Composer — Publish 3a, Task 4): the FIRST cross-vertical Pact edge
// in the Queue vertical, backing the Range exercise picker
// (GET /api/v1/queue/range/exercises) that lets a Queue account group be
// bound to a Range exercise_id.
//
// The single interaction here is a VERBATIM mirror of range-bff's own
// already-verified "ExerciseService.List — happy path" interaction (see
// services/range-bff/pacts/range-bff-range-svc-exercise.json): same
// description, same providerState string ("org has exercises"), same
// request/response shape. This is deliberate, not an oversight — range-svc's
// provider harness (services/range-svc/tests/integration/
// test_pact_provider.py) already has a List dispatch case and its
// _seed_exercise_state already recognizes "org has exercises", both added
// to make range-bff's own contract pass. Reusing the interaction verbatim
// means this new consumer needs ZERO changes to that harness — a different
// providerState string or request path would either raise
// "ValueError: Unknown ExerciseService gRPC method" or hit an unseeded-state
// failure that crashes the whole provider run.
//
// The contract JSON at ../../../pacts/queue-bff-range-svc-exercise.json is
// the authored source of truth. These tests guard that the committed
// contract is present, well-formed, and records the expected interaction —
// mirroring account_consumer_test.go's dependency-light style (stdlib
// testing, no testify, no pact-go DSL — queue-bff does not vendor testify).
//
// request.path is the raw gRPC method path
// ("/omnicore.range.exercise.v1.ExerciseService/List"); response.body is the
// unwrapped ListResponse ({"exercises": [...], "next_page_token": ...}) —
// NOT the browser→queue-bff REST envelope ({"data": [...]}). The REST
// envelope is asserted separately by internal/handlers/
// range_exercises_test.go's happy-path tests.
package consumer

import (
	"encoding/json"
	"os"
	"testing"
)

const exercisePactFile = "../../../pacts/queue-bff-range-svc-exercise.json"

// exercisePactContract is the full-fidelity shape of the exercise contract —
// pactContract (from account_consumer_test.go, same package) is
// shape-minimal for the consumer/provider/description/providerState
// fields, so this file defines its own struct only where it needs the
// request/response body too.
type exercisePactContract struct {
	Consumer struct {
		Name string `json:"name"`
	} `json:"consumer"`
	Provider struct {
		Name string `json:"name"`
	} `json:"provider"`
	Interactions []struct {
		Description   string `json:"description"`
		ProviderState string `json:"providerState"`
		Request       struct {
			Method  string            `json:"method"`
			Path    string            `json:"path"`
			Headers map[string]string `json:"headers"`
			Body    map[string]any    `json:"body"`
		} `json:"request"`
		Response struct {
			Status  int               `json:"status"`
			Headers map[string]string `json:"headers"`
			Body    struct {
				Exercises     []any  `json:"exercises"`
				NextPageToken string `json:"next_page_token"`
			} `json:"body"`
			MatchingRules struct {
				Body map[string]any `json:"body"`
			} `json:"matchingRules"`
		} `json:"response"`
	} `json:"interactions"`
	Metadata struct {
		PactSpecification struct {
			Version string `json:"version"`
		} `json:"pactSpecification"`
	} `json:"metadata"`
}

// loadExerciseContract reads and unmarshals the exercise contract JSON.
func loadExerciseContract(t *testing.T) exercisePactContract {
	t.Helper()
	data, err := os.ReadFile(exercisePactFile)
	if err != nil {
		t.Fatalf("pact contract must exist at %s: %v", exercisePactFile, err)
	}
	var c exercisePactContract
	if err := json.Unmarshal(data, &c); err != nil {
		t.Fatalf("pact contract must be valid JSON: %v", err)
	}
	return c
}

// TestPactContractExerciseFileExists guards that the exercise contract JSON
// is present at the expected path.
func TestPactContractExerciseFileExists(t *testing.T) {
	if _, err := os.Stat(exercisePactFile); err != nil {
		t.Fatalf("pact contract should be at services/queue-bff/pacts/queue-bff-range-svc-exercise.json: %v", err)
	}
}

// TestPact_ExerciseSvc_ConsumerAndProviderNames asserts the contract
// identifies queue-bff as consumer and range-svc as provider — this is the
// first queue-bff→range-svc Pact edge, so a typo here would silently
// register the contract under the wrong pacticipant pair on the broker.
func TestPact_ExerciseSvc_ConsumerAndProviderNames(t *testing.T) {
	c := loadExerciseContract(t)
	if c.Consumer.Name != "queue-bff" {
		t.Errorf("consumer.name = %q; want queue-bff", c.Consumer.Name)
	}
	if c.Provider.Name != "range-svc" {
		t.Errorf("provider.name = %q; want range-svc", c.Provider.Name)
	}
}

// TestPact_ExerciseSvc_ContractHasOneInteraction asserts the contract
// contains exactly the List interaction landed by this task.
func TestPact_ExerciseSvc_ContractHasOneInteraction(t *testing.T) {
	c := loadExerciseContract(t)
	if len(c.Interactions) != 1 {
		t.Errorf("exercise contract has %d interactions; want 1", len(c.Interactions))
	}
}

// TestPact_ExerciseSvc_List_Happy asserts the contract records the
// ExerciseService.List happy-path interaction.
func TestPact_ExerciseSvc_List_Happy(t *testing.T) {
	c := loadExerciseContract(t)
	for _, i := range c.Interactions {
		if i.Description == "ExerciseService.List — happy path" {
			return
		}
	}
	t.Error("contract must contain \"ExerciseService.List — happy path\" interaction")
}

// TestPact_ExerciseSvc_List_HasProviderState pins the EXACT providerState
// string this interaction reuses from range-bff's own proven contract —
// "org has exercises". This is the whole landmine-avoidance mechanism: the
// range provider harness's _seed_exercise_state already recognizes this
// exact string. A different string here would seed nothing and the List
// dispatch would return no exercises against an unseeded org, or (worse,
// for a differently-named RPC) crash the harness outright.
func TestPact_ExerciseSvc_List_HasProviderState(t *testing.T) {
	c := loadExerciseContract(t)
	const want = "org has exercises"
	for _, i := range c.Interactions {
		if i.Description == "ExerciseService.List — happy path" {
			if i.ProviderState != want {
				t.Errorf("ExerciseService.List provider state = %q; want %q", i.ProviderState, want)
			}
			return
		}
	}
	t.Fatal("ExerciseService.List — happy path interaction not found")
}

// TestPact_ExerciseSvc_List_RequestShape pins the raw gRPC request the
// consumer issues: a POST to the ExerciseService.List method path with an
// empty body (ListRequest has no required fields — org scoping happens via
// the forwarded x-tenant-id gRPC metadata, not a request field).
func TestPact_ExerciseSvc_List_RequestShape(t *testing.T) {
	c := loadExerciseContract(t)
	for _, i := range c.Interactions {
		if i.Description != "ExerciseService.List — happy path" {
			continue
		}
		if i.Request.Method != "POST" {
			t.Errorf("request.method = %q; want POST", i.Request.Method)
		}
		const wantPath = "/omnicore.range.exercise.v1.ExerciseService/List"
		if i.Request.Path != wantPath {
			t.Errorf("request.path = %q; want %q", i.Request.Path, wantPath)
		}
		if len(i.Request.Body) != 0 {
			t.Errorf("request.body = %v; want empty (ListRequest carries no required fields)", i.Request.Body)
		}
		return
	}
	t.Fatal("ExerciseService.List — happy path interaction not found")
}

// TestPact_ExerciseSvc_List_ResponseShape pins the ListResponse wire shape
// the queue-bff rangeclient.Client depends on: an "exercises" array
// (type-matched, so the provider's real exercise rows verify structurally
// rather than byte-for-byte) plus a next_page_token string.
func TestPact_ExerciseSvc_List_ResponseShape(t *testing.T) {
	c := loadExerciseContract(t)
	for _, i := range c.Interactions {
		if i.Description != "ExerciseService.List — happy path" {
			continue
		}
		if i.Response.Status != 200 {
			t.Errorf("response.status = %d; want 200", i.Response.Status)
		}
		if i.Response.Body.Exercises == nil {
			t.Error("response.body.exercises must be present (even if empty)")
		}
		if _, ok := i.Response.MatchingRules.Body["$.exercises"]; !ok {
			t.Error("response.matchingRules.body must type-match $.exercises")
		}
		return
	}
	t.Fatal("ExerciseService.List — happy path interaction not found")
}

// TestPact_ExerciseSvc_PactSpecificationVersion asserts the contract
// declares Pact V2, matching the hand-authored account/post contracts.
func TestPact_ExerciseSvc_PactSpecificationVersion(t *testing.T) {
	c := loadExerciseContract(t)
	if c.Metadata.PactSpecification.Version != "2.0.0" {
		t.Errorf("metadata.pactSpecification.version = %q; want 2.0.0", c.Metadata.PactSpecification.Version)
	}
}



